<?php if(!teachingCalendarReady()){echo '<p>Run the database migration first.</p>';return;}?>
<section class="card"><h2>Academic calendar</h2><p>Set the college calendar dates once. Manual class entry uses these fixed values. Retiring a setting removes it from new selections; existing classes are preserved. Add a replacement calendar to correct dates.</p><?php attForm('att_calendar_save');?><div class="form-grid"><?php attInput('academic_year','Academic year (e.g. 2026-2027)');attSelect('semester','Semester',['I'=>'I','II'=>'II'],'',true);attInput('valid_from','College term start','','date');attInput('valid_until','College term end','','date');?></div><button>Add calendar</button></form></section>
<section class="card"><h2>Class timings</h2><p>Add each allowed start/end pair, including double periods if used. Staff select a complete timing rather than typing times.</p><?php attForm('att_time_save');?><div class="form-grid"><?php attInput('start_time','Class start','','time');attInput('end_time','Class end','','time');?></div><button>Add timing</button></form></section>
<?php foreach(['calendar'=>'teaching_calendars','time'=>'teaching_time_slots']as $kind=>$table):?><section class="card"><h2><?=$kind==='calendar'?'Configured calendars':'Configured timings'?></h2><div class="table-wrap"><table><thead><tr><th>Setting</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach(all("SELECT * FROM $table ORDER BY id DESC")as $r):?><tr><td><?=e($kind==='calendar'?$r['academic_year'].' · Semester '.$r['semester'].' · '.$r['valid_from'].' to '.$r['valid_until']:$r['start_time'].' – '.$r['end_time'])?></td><td><?=$r['active']?'Active':'Retired'?></td><td><?php if($r['active']):attForm('att_calendar_retire');?><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="secondary">Retire for new entries</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endforeach;?>
